@charset "UTF-8";
:root { color-scheme: dark; font-family: Inter, "Segoe UI", system-ui, sans-serif; color: #e9e4dc; background: #07080f; font-synthesis: none; }
* { box-sizing: border-box; }
body { margin: 0; min-width: 280px; min-height: 100svh; background: radial-gradient(ellipse at 20% 0, #20283c 0, #0b0e18 48%, #07080f 100%); }
button { font: inherit; }
#game-root, .game-shell { position: relative; width: min(100%, 1440px); margin: 0 auto; min-height: 100svh; display: grid; align-content: center; isolation: isolate; }
#game-canvas, .game-canvas { display: block; width: 100%; height: auto; aspect-ratio: 16 / 9; background: #07080f; border: 1px solid #30384b; box-shadow: 0 28px 90px #0009; touch-action: none; user-select: none; -webkit-user-select: none; }
#game-overlay, .game-overlay { position: absolute; inset: 0; z-index: 4; display: grid; place-items: center; padding: 22px; overflow: auto; background: linear-gradient(110deg, #07080fd9, #0c132285); }
[hidden], #game-overlay[hidden], .game-overlay[hidden] { display: none !important; }
.game-panel { pointer-events: auto; position: relative; width: min(100%, 540px); max-height: calc(100svh - 40px); overflow: auto; padding: clamp(22px, 4vw, 46px); border: 1px solid #727e9859; border-top-color: #c4cce075; border-radius: 8px; background: linear-gradient(145deg, #1b2334f5, #0c111df7); box-shadow: 0 24px 90px #0009, inset 0 1px #ffffff08; }
.game-panel::before { content: ""; display: block; width: 44px; height: 3px; background: #e01a2b; margin-bottom: 24px; }
.game-panel h1 { font-size: clamp(32px, 6vw, 58px); line-height: .98; letter-spacing: .06em; margin: 0 0 16px; font-weight: 850; }
.game-panel h2 { margin: 0 0 16px; font-size: clamp(26px, 4vw, 38px); line-height: 1.1; }
.game-panel p, .game-panel li { color: #bbc5d6; line-height: 1.6; font-size: 14px; }
.game-panel strong { color: #f6eee5; }
.game-panel ul { padding-left: 20px; }
.game-panel small { color: #a8b3c8; line-height: 1.5; }
.game-kicker { color: #ffbf69 !important; text-transform: uppercase; letter-spacing: .2em; font-size: 10px !important; font-weight: 750; }
.game-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 24px; }
.game-button { appearance: none; min-height: 44px; padding: 11px 18px; border: 1px solid #73819880; border-radius: 5px; color: #f6eee5; background: #293448; cursor: pointer; font-size: 13px; font-weight: 700; line-height: 1.25; touch-action: manipulation; transition: background .15s, border-color .15s; }
.game-panel .game-button:first-of-type { background: #b91d30; border-color: #f85b6a; box-shadow: 0 4px 18px #a00e2426; }
.game-button:hover { background: #3a4860; border-color: #ced7e9; }
.game-panel .game-button:first-of-type:hover { background: #d0263c; }
.game-button:active { filter: brightness(.85); }
.game-button:focus-visible { outline: 3px solid #ffcf80; outline-offset: 3px; box-shadow: 0 0 0 6px #080d18; }
#game-canvas:focus-visible, .game-canvas:focus-visible { outline: 3px solid #ffcf80; outline-offset: -4px; }
.game-panel { min-width: 0; overflow-wrap: anywhere; scroll-padding: 12px; }
.game-panel > .game-button { margin: 6px 8px 6px 0; max-width: 100%; white-space: normal; }
.game-hud > span, #game-hud > span { white-space: nowrap; }
.game-button { max-width: 100%; overflow-wrap: anywhere; }
.game-button:disabled { opacity: .45; cursor: not-allowed; }
#game-hud, .game-hud { position: absolute; top: max(12px, env(safe-area-inset-top)); left: max(14px, env(safe-area-inset-left)); right: max(14px, env(safe-area-inset-right)); z-index: 3; display: flex; flex-wrap: wrap; align-items: center; gap: 8px 18px; padding: 10px 14px; border: 1px solid #a4b7d42b; border-radius: 5px; color: #e9e4dc; background: #080d18e6; font-size: 12px; font-weight: 650; font-variant-numeric: tabular-nums; pointer-events: none; }
.game-hud .game-button, #game-hud .game-button { pointer-events: auto; font-size: 11px; min-height: 36px; padding: 7px 12px; }
[data-hud="hp"] { color: #ff8691; }
[data-hud="silk"] { color: #b9e7ed; }
[data-hud="score"] { color: #ffcf8f; }
[data-hud="best"] { color: #a8b3c8; }
.game-stats { display: flex; flex-wrap: wrap; gap: 12px; padding: 16px 0; border-block: 1px solid #ffffff18; }
.game-help { color: #a8b3c8; font-size: 12px; line-height: 1.5; }
[data-touch-controls] .game-button { background: #182234c9; border-color: #bccce65c; color: #e5edff; user-select: none; -webkit-user-select: none; touch-action: none; }
.sr-only { position: absolute !important; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 600px) {
  #game-root, .game-shell { align-content: center; }
  #game-overlay, .game-overlay { padding: 12px; }
  .game-panel { padding: 22px; max-height: calc(100svh - 24px); }
  .game-panel::before { margin-bottom: 18px; }
  .game-panel p, .game-panel li { font-size: 14px; line-height: 1.5; }
  .game-panel h1 { font-size: clamp(28px, 8.5vw, 36px); line-height: 1.08; letter-spacing: .035em; }
  .game-panel .game-button { flex: 1 1 auto; }
  .game-panel > .game-button { display: block; width: 100%; margin: 10px 0 4px; }
  #game-hud, .game-hud { top: max(8px, env(safe-area-inset-top)); left: max(8px, env(safe-area-inset-left)); right: max(8px, env(safe-area-inset-right)); gap: 6px 10px; padding: 8px; font-size: 12px; background: #080d18f5; }
  #game-hud .game-button, .game-hud .game-button { min-height: 44px; padding: 7px 10px; font-size: 12px; }
}
@media (max-height: 480px) and (orientation: landscape) {
  .game-panel { padding: 18px 24px; max-width: 650px; }
  .game-panel::before { display: none; }
  .game-panel h1 { font-size: 30px; margin-bottom: 8px; }
  .game-panel h2 { font-size: 26px; }
  .game-panel p, .game-panel li { margin-block: 6px; font-size: 12px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation: none !important; transition: none !important; }
}
